// Read a prepared corpus without choosing how it was retrieved or curated.
//
// JSON Lines is the interchange format: one JSON object per physical line,
// with required string `id` and `text` fields. Other fields remain metadata.
// Serde parses JSON; standard buffered I/O supplies record boundaries. This
// reader does not normalize, filter, deduplicate, split, or approve the text.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeMap;
use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, Read};

/// One document already selected by the corpus-preparation workflow.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub struct PreparedDocument {
    pub id: String,
    pub text: String,
    #[serde(flatten)]
    pub metadata: BTreeMap<String, Value>,
}

/// Caller-selected bounds, independent of a dataset name or storage adapter.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ReadLimits {
    /// Maximum bytes in one physical JSON record, including its line ending.
    pub max_record_bytes: usize,
    pub max_documents: u64,
    /// Sum of decoded document text lengths in UTF-8 bytes, not source bytes.
    pub max_total_text_bytes: u64,
}

/// Counts only documents successfully returned to the caller.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
pub struct ReadProgress {
    pub documents: u64,
    pub text_bytes: u64,
}

#[derive(Debug)]
pub enum CorpusReadError {
    InvalidLimits(&'static str),
    Io {
        line: u64,
        source: io::Error,
    },
    RecordTooLarge {
        line: u64,
        limit: usize,
    },
    InvalidJson {
        line: u64,
        source: serde_json::Error,
    },
    EmptyField {
        line: u64,
        field: &'static str,
    },
    TooManyDocuments {
        limit: u64,
    },
    TextBudgetExceeded {
        line: u64,
        limit: u64,
    },
    CountOverflow,
}

impl fmt::Display for CorpusReadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidLimits(reason) => write!(f, "invalid corpus read limits: {reason}"),
            Self::Io { line, source } => write!(f, "cannot read corpus line {line}: {source}"),
            Self::RecordTooLarge { line, limit } => {
                write!(f, "corpus line {line} exceeds {limit} source bytes")
            }
            Self::InvalidJson { line, source } => {
                write!(f, "invalid document JSON on corpus line {line}: {source}")
            }
            Self::EmptyField { line, field } => {
                write!(f, "corpus line {line} has an empty {field}")
            }
            Self::TooManyDocuments { limit } => {
                write!(f, "corpus exceeds the {limit}-document read limit")
            }
            Self::TextBudgetExceeded { line, limit } => {
                write!(
                    f,
                    "corpus line {line} exceeds the {limit}-byte decoded-text budget"
                )
            }
            Self::CountOverflow => write!(f, "corpus count cannot be represented as u64"),
        }
    }
}

impl Error for CorpusReadError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io { source, .. } => Some(source),
            Self::InvalidJson { source, .. } => Some(source),
            _ => None,
        }
    }
}

/// A streaming reader over a file, memory buffer, database export, or any other
/// caller-provided buffered byte stream. It holds at most one source record.
///
/// After an error it yields no more documents. Earlier returned documents are
/// not rolled back; a caller needing all-or-nothing publication must stage its
/// own result until end of input. Empty input yields zero documents.
pub struct PreparedCorpusReader<R> {
    reader: R,
    limits: ReadLimits,
    buffer: Vec<u8>,
    progress: ReadProgress,
    finished: bool,
}

impl<R: BufRead> PreparedCorpusReader<R> {
    pub fn new(reader: R, limits: ReadLimits) -> Result<Self, CorpusReadError> {
        if limits.max_record_bytes == 0 || limits.max_record_bytes.checked_add(1).is_none() {
            return Err(CorpusReadError::InvalidLimits(
                "record capacity must be positive with room for one overflow byte",
            ));
        }
        if limits.max_documents == 0 || limits.max_total_text_bytes == 0 {
            return Err(CorpusReadError::InvalidLimits(
                "document and decoded-text capacities must be positive",
            ));
        }
        Ok(Self {
            reader,
            limits,
            buffer: Vec::new(),
            progress: ReadProgress::default(),
            finished: false,
        })
    }

    pub fn progress(&self) -> ReadProgress {
        self.progress
    }

    fn read_document(&mut self) -> Result<Option<PreparedDocument>, CorpusReadError> {
        let line = self
            .progress
            .documents
            .checked_add(1)
            .ok_or(CorpusReadError::CountOverflow)?;
        if self
            .reader
            .fill_buf()
            .map_err(|source| CorpusReadError::Io { line, source })?
            .is_empty()
        {
            return Ok(None);
        }
        if self.progress.documents == self.limits.max_documents {
            return Err(CorpusReadError::TooManyDocuments {
                limit: self.limits.max_documents,
            });
        }

        self.buffer.clear();
        // Standard Take bounds even a malformed record with no newline. The
        // extra byte distinguishes a record at the cap from one over the cap.
        (&mut self.reader)
            .take((self.limits.max_record_bytes + 1) as u64)
            .read_until(b'\n', &mut self.buffer)
            .map_err(|source| CorpusReadError::Io { line, source })?;
        if self.buffer.len() > self.limits.max_record_bytes {
            return Err(CorpusReadError::RecordTooLarge {
                line,
                limit: self.limits.max_record_bytes,
            });
        }

        // region:prepared-document-json
        let document: PreparedDocument = serde_json::from_slice(&self.buffer)
            .map_err(|source| CorpusReadError::InvalidJson { line, source })?;
        for (field, value) in [("id", &document.id), ("text", &document.text)] {
            if value.trim().is_empty() {
                return Err(CorpusReadError::EmptyField { line, field });
            }
        }
        // endregion:prepared-document-json

        let text_bytes = u64::try_from(document.text.len())
            .ok()
            .and_then(|bytes| self.progress.text_bytes.checked_add(bytes))
            .ok_or(CorpusReadError::CountOverflow)?;
        if text_bytes > self.limits.max_total_text_bytes {
            return Err(CorpusReadError::TextBudgetExceeded {
                line,
                limit: self.limits.max_total_text_bytes,
            });
        }
        self.progress = ReadProgress {
            documents: line,
            text_bytes,
        };
        Ok(Some(document))
    }
}

impl<R: BufRead> Iterator for PreparedCorpusReader<R> {
    type Item = Result<PreparedDocument, CorpusReadError>;

    // region:prepared-corpus-stream
    fn next(&mut self) -> Option<Self::Item> {
        if self.finished {
            return None;
        }
        match self.read_document() {
            Ok(Some(document)) => Some(Ok(document)),
            Ok(None) => {
                self.finished = true;
                None
            }
            Err(error) => {
                self.finished = true;
                Some(Err(error))
            }
        }
    }
    // endregion:prepared-corpus-stream
}

impl<R: BufRead> std::iter::FusedIterator for PreparedCorpusReader<R> {}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{BufReader, Cursor};

    fn limits() -> ReadLimits {
        ReadLimits {
            max_record_bytes: 256,
            max_documents: 10,
            max_total_text_bytes: 1024,
        }
    }

    #[test]
    fn preserves_unicode_escaped_newlines_and_metadata() {
        let source = br#"{"id":"source/7","text":"caf\u00e9\nnext","score":0.5,"origin":{"name":"fixture"}}"#;
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
        let document = reader.next().unwrap().unwrap();
        assert_eq!(document.id, "source/7");
        assert_eq!(document.text, "café\nnext");
        assert_eq!(document.metadata["score"], serde_json::json!(0.5));
        assert_eq!(document.metadata["origin"]["name"], "fixture");
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 10
            }
        );
        assert!(reader.next().is_none());
    }

    #[test]
    fn accepts_lf_crlf_and_a_final_record_without_newline() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n{\"id\":\"b\",\"text\":\"two\"}\r\n{\"id\":\"c\",\"text\":\"three\"}";
        let documents =
            PreparedCorpusReader::new(BufReader::with_capacity(3, &source[..]), limits())
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
        assert_eq!(
            documents
                .iter()
                .map(|document| document.id.as_str())
                .collect::<Vec<_>>(),
            ["a", "b", "c"]
        );
    }

    #[test]
    fn empty_input_is_an_empty_stream() {
        let mut reader = PreparedCorpusReader::new(Cursor::new(b""), limits()).unwrap();
        assert!(reader.next().is_none());
        assert!(reader.next().is_none());
        assert_eq!(reader.progress(), ReadProgress::default());
    }

    #[test]
    fn malformed_record_stops_without_counting_it_or_skipping_forward() {
        let source =
            b"{\"id\":\"a\",\"text\":\"one\"}\nnot-json\n{\"id\":\"b\",\"text\":\"two\"}\n";
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::InvalidJson { line: 2, .. })
        ));
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 3
            }
        );
        assert!(reader.next().is_none());
    }

    #[test]
    fn rejects_blank_lines_invalid_utf8_and_incomplete_schema() {
        for source in [
            &b"\n"[..],
            &b"{\"id\":\"a\",\"text\":\"\xff\"}\n"[..],
            &b"{\"id\":\"a\"}\n"[..],
            &b"{\"id\":1,\"text\":\"one\"}\n"[..],
            &b"{\"id\":\"a\",\"id\":\"b\",\"text\":\"one\"}\n"[..],
            &b"[{\"id\":\"a\",\"text\":\"one\"}]\n"[..],
        ] {
            let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
            assert!(matches!(
                reader.next().unwrap(),
                Err(CorpusReadError::InvalidJson { line: 1, .. })
            ));
            assert!(reader.next().is_none());
        }
    }

    #[test]
    fn required_values_cannot_be_empty_but_text_is_never_trimmed() {
        for (source, field) in [
            (r#"{"id":" ","text":"one"}"#, "id"),
            (r#"{"id":"a","text":"\n\t"}"#, "text"),
        ] {
            let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
            assert!(
                matches!(reader.next().unwrap(), Err(CorpusReadError::EmptyField { field: actual, .. }) if actual == field)
            );
        }
        let mut reader =
            PreparedCorpusReader::new(Cursor::new(r#"{"id":"a","text":" one \n"}"#), limits())
                .unwrap();
        assert_eq!(reader.next().unwrap().unwrap().text, " one \n");
    }

    #[test]
    fn record_bound_is_exact_and_includes_the_line_ending() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n";
        let exact = ReadLimits {
            max_record_bytes: source.len(),
            ..limits()
        };
        assert!(
            PreparedCorpusReader::new(Cursor::new(source), exact)
                .unwrap()
                .next()
                .unwrap()
                .is_ok()
        );
        let short = ReadLimits {
            max_record_bytes: source.len() - 1,
            ..limits()
        };
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), short).unwrap();
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::RecordTooLarge { line: 1, .. })
        ));
        assert_eq!(reader.progress(), ReadProgress::default());
        assert!(reader.next().is_none());
    }

    #[test]
    fn bounds_an_unterminated_oversized_record_before_json_parsing() {
        let source = vec![b'x'; 4096];
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::RecordTooLarge {
                line: 1,
                limit: 256
            })
        ));
        assert_eq!(reader.buffer.len(), 257);
    }

    #[test]
    fn document_and_text_limits_do_not_count_a_failed_document() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n{\"id\":\"b\",\"text\":\"two\"}\n";
        let mut reader = PreparedCorpusReader::new(
            Cursor::new(source),
            ReadLimits {
                max_documents: 1,
                ..limits()
            },
        )
        .unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::TooManyDocuments { limit: 1 })
        ));
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 3
            }
        );

        let mut reader = PreparedCorpusReader::new(
            Cursor::new(source),
            ReadLimits {
                max_total_text_bytes: 5,
                ..limits()
            },
        )
        .unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::TextBudgetExceeded { line: 2, limit: 5 })
        ));
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 3
            }
        );
        assert!(reader.next().is_none());
    }

    #[test]
    fn exact_document_and_text_caps_still_allow_end_of_input() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n";
        let mut reader = PreparedCorpusReader::new(
            Cursor::new(source),
            ReadLimits {
                max_documents: 1,
                max_total_text_bytes: 3,
                ..limits()
            },
        )
        .unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(reader.next().is_none());
    }

    struct BrokenRead;

    impl Read for BrokenRead {
        fn read(&mut self, _: &mut [u8]) -> io::Result<usize> {
            Err(io::Error::other("injected read failure"))
        }
    }

    #[test]
    fn io_error_is_not_end_of_input() {
        let mut reader = PreparedCorpusReader::new(BufReader::new(BrokenRead), limits()).unwrap();
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::Io { line: 1, .. })
        ));
        assert!(reader.next().is_none());
        assert_eq!(reader.progress(), ReadProgress::default());
    }

    // region:loading-is-not-preparation
    #[test]
    fn loader_does_not_curate_repeated_ids_or_text() {
        let source =
            b"{\"id\":\"same\",\"text\":\"same text\"}\n{\"id\":\"same\",\"text\":\"same text\"}\n";
        let documents = PreparedCorpusReader::new(Cursor::new(source), limits())
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(documents.len(), 2);
        assert_eq!(documents[0], documents[1]);
    }
    // endregion:loading-is-not-preparation

    #[test]
    fn invalid_limits_are_rejected_before_reading() {
        for bad in [
            ReadLimits {
                max_record_bytes: 0,
                ..limits()
            },
            ReadLimits {
                max_record_bytes: usize::MAX,
                ..limits()
            },
            ReadLimits {
                max_documents: 0,
                ..limits()
            },
            ReadLimits {
                max_total_text_bytes: 0,
                ..limits()
            },
        ] {
            assert!(matches!(
                PreparedCorpusReader::new(BufReader::new(BrokenRead), bad),
                Err(CorpusReadError::InvalidLimits(_))
            ));
        }
    }
}

// Standalone metadata for the existing tokenizer's frozen ranks and training inputs.
// Vocabulary, operand validation, document controls and decoding remain in bpe.rs.

use super::bpe::{BpeTokenizer, CONTENT_ID_OFFSET, TOKENIZER_LAYOUT_VERSION, TokenizerLayout};
use super::bpe_trainer::TokenPair;
use super::policy::{TokenizerError, TokenizerLimits, TokenizerPolicy, TrainingBinding};
use serde::{Deserialize, Serialize};
use std::io::{self, Write};

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ArtifactMerge {
    pub candidate_count: u64,
    pub left: u32,
    pub rank: usize,
    pub replacements: u64,
    pub right: u32,
    pub token_id: u32,
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct EfficiencyCounters {
    pub content_tokens: u64,
    pub control_tokens: u64,
    pub input_bytes: u64,
    pub training_documents: u64,
}

impl EfficiencyCounters {
    /// Document controls are excluded; zero input bytes gives no ratio.
    pub fn content_tokens_per_byte(&self) -> Option<f64> {
        (self.input_bytes != 0).then(|| self.content_tokens as f64 / self.input_bytes as f64)
    }
}

/// Fixed field order and learned-rank array order define this JSON payload.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct TokenizerArtifact {
    pub counters: EfficiencyCounters,
    pub layout_version: u32,
    pub merges: Vec<ArtifactMerge>,
    pub policy: TokenizerPolicy,
    pub schema_version: u32,
    pub trainer_semantics: String,
    pub training: TrainingBinding,
}

impl TokenizerArtifact {
    // region:validate-tokenizer-artifact
    /// Validate metadata, then ask the existing tokenizer to build its vocabulary.
    pub fn validate(&self, limits: TokenizerLimits) -> Result<BpeTokenizer, TokenizerError> {
        limits.validate()?;
        self.policy.validate()?;
        self.training.validate()?;
        if self.schema_version != 1
            || self.layout_version != TOKENIZER_LAYOUT_VERSION
            || self.trainer_semantics != "overlapping-count-leftmost-replace-v1"
        {
            return Err(TokenizerError::Artifact(
                "unknown tokenizer format or semantics",
            ));
        }
        if self.merges.len() > limits.max_nodes {
            return Err(TokenizerError::Resource(
                "merge table exceeds working capacity",
            ));
        }
        if self.merges.len() > self.policy.merge_count
            || (self.policy.exact_merge_count && self.merges.len() != self.policy.merge_count)
        {
            return Err(TokenizerError::Artifact(
                "artifact violates requested merge count",
            ));
        }
        if self.counters.control_tokens
            != self
                .counters
                .training_documents
                .checked_mul(2)
                .ok_or(TokenizerError::Overflow)?
            || self.counters.content_tokens > self.counters.input_bytes
        {
            return Err(TokenizerError::Artifact("inconsistent efficiency counters"));
        }
        let layout = TokenizerLayout::new(self.merges.len())?;
        let mut pairs = Vec::new();
        pairs
            .try_reserve_exact(self.merges.len())
            .map_err(|_| TokenizerError::Resource("merge operand allocation failed"))?;
        let mut reduction = 0u64;
        for (rank, rule) in self.merges.iter().enumerate() {
            if rule.rank != rank
                || layout.merge_token_id(rank) != Some(rule.token_id)
                || rule.replacements == 0
                || rule.replacements > rule.candidate_count
            {
                return Err(TokenizerError::Artifact("invalid rank or merge count"));
            }
            let left = rule
                .left
                .checked_sub(CONTENT_ID_OFFSET)
                .ok_or(TokenizerError::Artifact(
                    "control ID cannot be a merge operand",
                ))?;
            let right =
                rule.right
                    .checked_sub(CONTENT_ID_OFFSET)
                    .ok_or(TokenizerError::Artifact(
                        "control ID cannot be a merge operand",
                    ))?;
            pairs.push(TokenPair::new(left, right));
            reduction = reduction
                .checked_add(rule.replacements)
                .ok_or(TokenizerError::Overflow)?;
        }
        if self.counters.input_bytes.checked_sub(reduction) != Some(self.counters.content_tokens) {
            return Err(TokenizerError::Artifact(
                "merge reductions disagree with content count",
            ));
        }
        // This single constructor owns prior-rank operands, duplicate pairs,
        // byte expansions and their bounds; there is no second vocabulary here.
        Ok(BpeTokenizer::from_merge_pairs_bounded(
            &pairs,
            limits.max_token_bytes,
            limits.max_vocabulary_bytes,
        )?)
    }
    // endregion:validate-tokenizer-artifact

    pub fn canonical_bytes(&self, limits: TokenizerLimits) -> Result<Vec<u8>, TokenizerError> {
        self.validate(limits)?;
        let mut writer = BoundedPayload {
            bytes: Vec::new(),
            cap: limits.max_artifact_bytes - 1,
        };
        serde_json::to_writer(&mut writer, self).map_err(|_| {
            TokenizerError::Resource(
                "tokenizer payload exceeds artifact capacity or allocation failed",
            )
        })?;
        writer
            .bytes
            .try_reserve_exact(1)
            .map_err(|_| TokenizerError::Resource("payload allocation failed"))?;
        writer.bytes.push(b'\n');
        Ok(writer.bytes)
    }

    /// Parse bounded JSON metadata. Tokenizer construction still follows validation.
    pub fn from_bytes(bytes: &[u8], limits: TokenizerLimits) -> Result<Self, TokenizerError> {
        limits.validate()?;
        if bytes.len() > limits.max_artifact_bytes {
            return Err(TokenizerError::Resource(
                "tokenizer payload exceeds artifact capacity",
            ));
        }
        let artifact: Self = serde_json::from_slice(bytes)
            .map_err(|error| TokenizerError::Input(error.to_string()))?;
        artifact.validate(limits)?;
        Ok(artifact)
    }
}

struct BoundedPayload {
    bytes: Vec<u8>,
    cap: usize,
}

impl Write for BoundedPayload {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        let size = self
            .bytes
            .len()
            .checked_add(bytes.len())
            .filter(|size| *size <= self.cap)
            .ok_or_else(|| io::Error::other("payload capacity"))?;
        self.bytes
            .try_reserve_exact(size - self.bytes.len())
            .map_err(|_| io::Error::other("payload allocation"))?;
        self.bytes.extend_from_slice(bytes);
        Ok(bytes.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

//! Application and exact reversal of a frozen byte-pair rank table.
//!
//! Layout version 1 reserves `0` and `1` for document controls. Content IDs are
//! the scalar trainer's training-space IDs shifted by two, so every possible byte keeps
//! a lossless fallback representation.

use std::collections::BTreeSet;
use std::error::Error;
use std::fmt;

use super::bpe_trainer::{BYTE_TOKEN_COUNT, BpeTraining, TokenPair, replace_pair_left_to_right};
use super::policy::{TokenizerError, TokenizerLimits};

// region:token-id-layout
/// Serialized layout version retained from the first course's Chapter 4.
pub const TOKENIZER_LAYOUT_VERSION: u32 = 1;
/// Marks the beginning of one encoded document.
pub const BOS_TOKEN_ID: u32 = 0;
/// Marks the end of one encoded document.
pub const EOS_TOKEN_ID: u32 = 1;
/// Maps every scalar training-space ID into the content namespace.
pub const CONTENT_ID_OFFSET: u32 = 2;
/// First content ID representing one raw byte.
pub const FIRST_BYTE_TOKEN_ID: u32 = CONTENT_ID_OFFSET;
/// Last content ID representing one raw byte.
pub const LAST_BYTE_TOKEN_ID: u32 = CONTENT_ID_OFFSET + BYTE_TOKEN_COUNT - 1;
/// Content ID assigned to merge rank zero.
pub const FIRST_MERGE_TOKEN_ID: u32 = LAST_BYTE_TOKEN_ID + 1;

/// The fixed fields and vocabulary extent of tokenizer layout version 1.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct TokenizerLayout {
    merge_count: usize,
    vocabulary_size: usize,
}

impl TokenizerLayout {
    /// Validates that every content symbol can be represented by a `u32` ID.
    pub fn new(merge_count: usize) -> Result<Self, BpeTokenizerError> {
        let vocabulary_size = usize::try_from(FIRST_MERGE_TOKEN_ID)
            .ok()
            .and_then(|base| base.checked_add(merge_count))
            .ok_or(BpeTokenizerError::LayoutOverflow { merge_count })?;
        let highest_token = vocabulary_size
            .checked_sub(1)
            .and_then(|value| u32::try_from(value).ok())
            .ok_or(BpeTokenizerError::LayoutOverflow { merge_count })?;
        if merge_count > 0 && highest_token < FIRST_MERGE_TOKEN_ID {
            return Err(BpeTokenizerError::LayoutOverflow { merge_count });
        }
        Ok(Self {
            merge_count,
            vocabulary_size,
        })
    }

    /// Returns the serialized layout version.
    pub const fn version(self) -> u32 {
        TOKENIZER_LAYOUT_VERSION
    }

    /// Returns the number of frozen merge ranks.
    pub const fn merge_count(self) -> usize {
        self.merge_count
    }

    /// Returns the complete number of control and content IDs.
    pub const fn vocabulary_size(self) -> usize {
        self.vocabulary_size
    }

    /// Maps a raw byte to its one-byte content token.
    pub const fn byte_token_id(self, byte: u8) -> u32 {
        FIRST_BYTE_TOKEN_ID + byte as u32
    }

    /// Returns the final content ID assigned to a valid zero-based rank.
    pub fn merge_token_id(self, rank: usize) -> Option<u32> {
        if rank >= self.merge_count {
            return None;
        }
        usize::try_from(FIRST_MERGE_TOKEN_ID)
            .ok()
            .and_then(|base| base.checked_add(rank))
            .and_then(|token| u32::try_from(token).ok())
    }
}
// endregion:token-id-layout

/// One frozen rule expressed in both trainer and final content namespaces.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BpeMergeRule {
    rank: usize,
    training_pair: TokenPair,
    training_token_id: u32,
    content_pair: TokenPair,
    content_token_id: u32,
}

impl BpeMergeRule {
    /// Returns the zero-based application order.
    pub const fn rank(&self) -> usize {
        self.rank
    }

    /// Returns the scalar training-space pair before the layout offset.
    pub const fn training_pair(&self) -> TokenPair {
        self.training_pair
    }

    /// Returns the scalar training-space token assigned to this rank.
    pub const fn training_token_id(&self) -> u32 {
        self.training_token_id
    }

    /// Returns the pair used while encoding final content IDs.
    pub const fn content_pair(&self) -> TokenPair {
        self.content_pair
    }

    /// Returns the final content ID assigned to this rank.
    pub const fn content_token_id(&self) -> u32 {
        self.content_token_id
    }
}

/// One rank that changed a particular input while encoding.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BpeMergeApplication {
    rank: usize,
    replacements: usize,
    before: Vec<u32>,
    after: Vec<u32>,
}

impl BpeMergeApplication {
    /// Returns the applied rank.
    pub const fn rank(&self) -> usize {
        self.rank
    }

    /// Returns how many non-overlapping occurrences changed.
    pub const fn replacements(&self) -> usize {
        self.replacements
    }

    /// Returns the input to this rank.
    pub fn before(&self) -> &[u32] {
        &self.before
    }

    /// Returns the output from this rank.
    pub fn after(&self) -> &[u32] {
        &self.after
    }
}

/// Inspectable evidence for one ranked content encoding.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BpeEncodingTrace {
    initial_tokens: Vec<u32>,
    applications: Vec<BpeMergeApplication>,
    content_tokens: Vec<u32>,
}

impl BpeEncodingTrace {
    /// Returns byte IDs before any merge rank runs.
    pub fn initial_tokens(&self) -> &[u32] {
        &self.initial_tokens
    }

    /// Returns only ranks that changed this input, in application order.
    pub fn applications(&self) -> &[BpeMergeApplication] {
        &self.applications
    }

    /// Returns the canonical content sequence after all ranks.
    pub fn content_tokens(&self) -> &[u32] {
        &self.content_tokens
    }
}

/// An owned, deterministic byte-level BPE tokenizer.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BpeTokenizer {
    layout: TokenizerLayout,
    merge_rules: Vec<BpeMergeRule>,
    training_vocabulary: Vec<Vec<u8>>,
}

impl BpeTokenizer {
    /// Copies the ranks and byte expansions from a validated scalar training result.
    pub fn from_training(training: &BpeTraining) -> Result<Self, BpeTokenizerError> {
        let layout = TokenizerLayout::new(training.rules().len())?;
        let merge_rules = training
            .rules()
            .iter()
            .map(|rule| {
                let training_pair = rule.pair();
                BpeMergeRule {
                    rank: rule.rank(),
                    training_pair,
                    training_token_id: rule.token_id(),
                    content_pair: TokenPair::new(
                        training_pair.left() + CONTENT_ID_OFFSET,
                        training_pair.right() + CONTENT_ID_OFFSET,
                    ),
                    content_token_id: rule.token_id() + CONTENT_ID_OFFSET,
                }
            })
            .collect();

        Ok(Self {
            layout,
            merge_rules,
            training_vocabulary: training.vocabulary().to_vec(),
        })
    }

    /// Builds a frozen tokenizer from ordered scalar training-space pairs.
    pub fn from_merge_pairs(pairs: &[TokenPair]) -> Result<Self, BpeTokenizerError> {
        Self::build_from_merge_pairs(pairs, None)
    }

    /// Uses the same rank/layout validation, with bounds checked before byte expansion.
    pub fn from_merge_pairs_bounded(
        pairs: &[TokenPair],
        max_token_bytes: usize,
        max_vocabulary_bytes: usize,
    ) -> Result<Self, BpeTokenizerError> {
        if max_token_bytes == 0 || max_vocabulary_bytes < BYTE_TOKEN_COUNT as usize {
            return Err(BpeTokenizerError::Capacity(
                "byte vocabulary exceeds capacity",
            ));
        }
        Self::build_from_merge_pairs(pairs, Some((max_token_bytes, max_vocabulary_bytes)))
    }

    fn build_from_merge_pairs(
        pairs: &[TokenPair],
        limits: Option<(usize, usize)>,
    ) -> Result<Self, BpeTokenizerError> {
        let layout = TokenizerLayout::new(pairs.len())?;
        // Every valid new symbol expands to at least two bytes. Refuse a
        // plainly impossible bound before reserving the rank or vocabulary rows.
        if let Some((token_limit, vocabulary_limit)) = limits {
            let minimum_bytes = pairs
                .len()
                .checked_mul(2)
                .and_then(|bytes| bytes.checked_add(BYTE_TOKEN_COUNT as usize))
                .ok_or(BpeTokenizerError::Capacity(
                    "vocabulary lower bound overflow",
                ))?;
            if minimum_bytes > vocabulary_limit || (!pairs.is_empty() && token_limit < 2) {
                return Err(BpeTokenizerError::Capacity(
                    "minimum vocabulary exceeds capacity",
                ));
            }
        }
        let mut training_vocabulary = (u8::MIN..=u8::MAX)
            .map(|byte| vec![byte])
            .collect::<Vec<_>>();
        training_vocabulary
            .try_reserve_exact(pairs.len())
            .map_err(|_| BpeTokenizerError::Capacity("vocabulary row allocation failed"))?;
        let mut merge_rules = Vec::new();
        merge_rules
            .try_reserve_exact(pairs.len())
            .map_err(|_| BpeTokenizerError::Capacity("merge table allocation failed"))?;
        let mut seen_pairs = BTreeSet::new();
        let mut vocabulary_bytes = BYTE_TOKEN_COUNT as usize;

        for (rank, &training_pair) in pairs.iter().enumerate() {
            let rank_id = u32::try_from(rank)
                .ok()
                .and_then(|rank| BYTE_TOKEN_COUNT.checked_add(rank))
                .ok_or(BpeTokenizerError::LayoutOverflow {
                    merge_count: pairs.len(),
                })?;
            for operand in [training_pair.left(), training_pair.right()] {
                if operand >= rank_id {
                    return Err(BpeTokenizerError::UnknownMergeOperand {
                        rank,
                        token_id: operand,
                    });
                }
            }
            if !seen_pairs.insert(training_pair) {
                return Err(BpeTokenizerError::DuplicateMergePair {
                    rank,
                    left: training_pair.left(),
                    right: training_pair.right(),
                });
            }

            let left_bytes = training_vocabulary
                .get(usize::try_from(training_pair.left()).unwrap_or(usize::MAX))
                .ok_or(BpeTokenizerError::UnknownMergeOperand {
                    rank,
                    token_id: training_pair.left(),
                })?;
            let right_bytes = training_vocabulary
                .get(usize::try_from(training_pair.right()).unwrap_or(usize::MAX))
                .ok_or(BpeTokenizerError::UnknownMergeOperand {
                    rank,
                    token_id: training_pair.right(),
                })?;
            let length = left_bytes.len().checked_add(right_bytes.len()).ok_or(
                BpeTokenizerError::Capacity("token expansion length overflow"),
            )?;
            vocabulary_bytes =
                vocabulary_bytes
                    .checked_add(length)
                    .ok_or(BpeTokenizerError::Capacity(
                        "vocabulary expansion length overflow",
                    ))?;
            if limits.is_some_and(|(token_limit, vocabulary_limit)| {
                length > token_limit || vocabulary_bytes > vocabulary_limit
            }) {
                return Err(BpeTokenizerError::Capacity(
                    "token or vocabulary expansion exceeds capacity",
                ));
            }
            let mut merged_bytes = Vec::new();
            merged_bytes
                .try_reserve_exact(length)
                .map_err(|_| BpeTokenizerError::Capacity("token expansion allocation failed"))?;
            merged_bytes.extend_from_slice(left_bytes);
            merged_bytes.extend_from_slice(right_bytes);

            let content_pair = TokenPair::new(
                training_pair.left().checked_add(CONTENT_ID_OFFSET).ok_or(
                    BpeTokenizerError::LayoutOverflow {
                        merge_count: pairs.len(),
                    },
                )?,
                training_pair.right().checked_add(CONTENT_ID_OFFSET).ok_or(
                    BpeTokenizerError::LayoutOverflow {
                        merge_count: pairs.len(),
                    },
                )?,
            );
            let content_token_id = rank_id.checked_add(CONTENT_ID_OFFSET).ok_or(
                BpeTokenizerError::LayoutOverflow {
                    merge_count: pairs.len(),
                },
            )?;
            merge_rules.push(BpeMergeRule {
                rank,
                training_pair,
                training_token_id: rank_id,
                content_pair,
                content_token_id,
            });
            training_vocabulary.push(merged_bytes);
        }

        Ok(Self {
            layout,
            merge_rules,
            training_vocabulary,
        })
    }

    /// Returns the validated layout extent.
    pub const fn layout(&self) -> TokenizerLayout {
        self.layout
    }

    /// Returns every rule in ascending rank order.
    pub fn merge_rules(&self) -> &[BpeMergeRule] {
        &self.merge_rules
    }

    /// Returns a content token's byte expansion; controls and unknown IDs have none.
    pub fn token_bytes(&self, content_token_id: u32) -> Option<&[u8]> {
        let training_id = content_token_id.checked_sub(CONTENT_ID_OFFSET)?;
        usize::try_from(training_id)
            .ok()
            .and_then(|index| self.training_vocabulary.get(index))
            .map(Vec::as_slice)
    }

    // region:ranked-content-encoding
    fn initial_content_tokens(&self, bytes: &[u8]) -> Vec<u32> {
        bytes
            .iter()
            .map(|byte| self.layout.byte_token_id(*byte))
            .collect()
    }

    fn apply_ranked_merges(
        &self,
        mut content_tokens: Vec<u32>,
        mut observe: impl FnMut(&BpeMergeRule, usize, &[u32], &[u32]),
    ) -> Vec<u32> {
        for rule in &self.merge_rules {
            let before = content_tokens;
            let (after, replacements) =
                replace_pair_left_to_right(&before, rule.content_pair, rule.content_token_id);
            if replacements > 0 {
                observe(rule, replacements, &before, &after);
            }
            content_tokens = after;
        }
        content_tokens
    }

    /// Encodes bytes and records every rank that changed the sequence.
    pub fn encode_content_with_trace(&self, bytes: &[u8]) -> BpeEncodingTrace {
        let initial_tokens = self.initial_content_tokens(bytes);
        let mut applications = Vec::new();
        let content_tokens = self.apply_ranked_merges(
            initial_tokens.clone(),
            |rule, replacements, before, after| {
                applications.push(BpeMergeApplication {
                    rank: rule.rank,
                    replacements,
                    before: before.to_vec(),
                    after: after.to_vec(),
                });
            },
        );

        BpeEncodingTrace {
            initial_tokens,
            applications,
            content_tokens,
        }
    }

    /// Encodes arbitrary bytes into the canonical rank-ordered content sequence.
    pub fn encode_content(&self, bytes: &[u8]) -> Vec<u32> {
        let initial_tokens = self.initial_content_tokens(bytes);
        self.apply_ranked_merges(initial_tokens, |_, _, _, _| {})
    }

    /// Encodes a valid UTF-8 string through the same byte boundary.
    pub fn encode_utf8(&self, text: &str) -> Vec<u32> {
        self.encode_content(text.as_bytes())
    }

    /// Apply this tokenizer's existing ranks using a bounded live-adjacency queue.
    pub fn encode_content_bounded(
        &self,
        bytes: &[u8],
        limits: TokenizerLimits,
    ) -> Result<Vec<u32>, TokenizerError> {
        super::encoding::encode_bytes(self, bytes, limits)
    }

    /// Read one bounded whole document; read chunks do not introduce BPE boundaries.
    pub fn encode_reader_bounded<R: std::io::Read>(
        &self,
        reader: R,
        limits: TokenizerLimits,
    ) -> Result<Vec<u32>, TokenizerError> {
        super::encoding::encode_reader(self, reader, limits)
    }
    // endregion:ranked-content-encoding

    // region:document-wrapping
    /// Encodes content first, then adds controls that never enter a merge pass.
    pub fn encode_document(&self, bytes: &[u8]) -> Vec<u32> {
        let content = self.encode_content(bytes);
        Self::frame_content(content).expect("document frame allocation failed")
    }

    /// Use the bounded strategy, then the same structural control insertion.
    pub fn encode_document_bounded(
        &self,
        bytes: &[u8],
        limits: TokenizerLimits,
    ) -> Result<Vec<u32>, TokenizerError> {
        Ok(Self::frame_content(
            self.encode_content_bounded(bytes, limits)?,
        )?)
    }

    fn frame_content(content: Vec<u32>) -> Result<Vec<u32>, BpeTokenizerError> {
        let size = content
            .len()
            .checked_add(2)
            .ok_or(BpeTokenizerError::Capacity("document frame size overflow"))?;
        let mut document = Vec::new();
        document
            .try_reserve_exact(size)
            .map_err(|_| BpeTokenizerError::Capacity("document frame allocation failed"))?;
        document.push(BOS_TOKEN_ID);
        document.extend(content);
        document.push(EOS_TOKEN_ID);
        Ok(document)
    }

    /// Encodes a UTF-8 document and adds its endpoint controls.
    pub fn encode_utf8_document(&self, text: &str) -> Vec<u32> {
        self.encode_document(text.as_bytes())
    }

    /// Validates one wrapped document and recovers its exact content bytes.
    pub fn decode_document(&self, document: &[u32]) -> Result<Vec<u8>, BpeTokenizerError> {
        self.decode_tokens(Self::document_content(document)?, 1, None)
    }

    /// Validate the same frame, then bound the reconstructed document bytes.
    pub fn decode_document_bounded(
        &self,
        document: &[u32],
        limits: TokenizerLimits,
    ) -> Result<Vec<u8>, TokenizerError> {
        limits.validate()?;
        let content = Self::document_content(document)?;
        if content.len() > limits.max_nodes {
            return Err(TokenizerError::Resource("decoding token capacity exceeded"));
        }
        Ok(self.decode_tokens(content, 1, Some(limits.max_nodes))?)
    }

    fn document_content(document: &[u32]) -> Result<&[u32], BpeTokenizerError> {
        if document.len() < 2 {
            return Err(BpeTokenizerError::DocumentTooShort {
                length: document.len(),
            });
        }
        if document[0] != BOS_TOKEN_ID {
            return Err(BpeTokenizerError::ExpectedBos { found: document[0] });
        }
        let last = document.len() - 1;
        if document[last] != EOS_TOKEN_ID {
            return Err(BpeTokenizerError::ExpectedEos {
                found: document[last],
            });
        }
        for (position, &token_id) in document[1..last].iter().enumerate() {
            if token_id == BOS_TOKEN_ID || token_id == EOS_TOKEN_ID {
                return Err(BpeTokenizerError::InteriorControlToken {
                    position: position + 1,
                    token_id,
                });
            }
        }
        Ok(&document[1..last])
    }
    // endregion:document-wrapping

    // region:byte-exact-decoding
    /// Concatenates content-token expansions without interpreting them as text.
    pub fn decode_content(&self, content: &[u32]) -> Result<Vec<u8>, BpeTokenizerError> {
        self.decode_content_using_limit(content, None)
    }

    /// Apply the existing content validation and expansion with an output byte cap.
    pub fn decode_content_bounded(
        &self,
        content: &[u32],
        limits: TokenizerLimits,
    ) -> Result<Vec<u8>, TokenizerError> {
        limits.validate()?;
        if content.len() > limits.max_nodes {
            return Err(TokenizerError::Resource("decoding token capacity exceeded"));
        }
        Ok(self.decode_content_using_limit(content, Some(limits.max_nodes))?)
    }

    fn decode_content_using_limit(
        &self,
        content: &[u32],
        max_bytes: Option<usize>,
    ) -> Result<Vec<u8>, BpeTokenizerError> {
        for (position, &token_id) in content.iter().enumerate() {
            if token_id == BOS_TOKEN_ID || token_id == EOS_TOKEN_ID {
                return Err(BpeTokenizerError::ControlTokenInContent { position, token_id });
            }
        }
        self.decode_tokens(content, 0, max_bytes)
    }

    /// Decodes content bytes, then requires the result to be valid UTF-8.
    pub fn decode_content_utf8(&self, content: &[u32]) -> Result<String, BpeTokenizerError> {
        strict_utf8(self.decode_content(content)?)
    }

    /// Bound byte reconstruction before the same strict UTF-8 conversion.
    pub fn decode_content_utf8_bounded(
        &self,
        content: &[u32],
        limits: TokenizerLimits,
    ) -> Result<String, TokenizerError> {
        Ok(strict_utf8(self.decode_content_bounded(content, limits)?)?)
    }

    /// Decodes a wrapped document, then requires the result to be valid UTF-8.
    pub fn decode_document_utf8(&self, document: &[u32]) -> Result<String, BpeTokenizerError> {
        strict_utf8(self.decode_document(document)?)
    }

    pub fn decode_document_utf8_bounded(
        &self,
        document: &[u32],
        limits: TokenizerLimits,
    ) -> Result<String, TokenizerError> {
        Ok(strict_utf8(
            self.decode_document_bounded(document, limits)?,
        )?)
    }
    // endregion:byte-exact-decoding

    fn decode_tokens(
        &self,
        tokens: &[u32],
        position_offset: usize,
        max_bytes: Option<usize>,
    ) -> Result<Vec<u8>, BpeTokenizerError> {
        let mut size = 0usize;
        for (index, &token_id) in tokens.iter().enumerate() {
            let expansion = self
                .token_bytes(token_id)
                .ok_or(BpeTokenizerError::UnknownToken {
                    position: index + position_offset,
                    token_id,
                })?;
            size = size
                .checked_add(expansion.len())
                .ok_or(BpeTokenizerError::Capacity("decoded byte length overflow"))?;
            if max_bytes.is_some_and(|cap| size > cap) {
                return Err(BpeTokenizerError::Capacity(
                    "decoded bytes exceed document capacity",
                ));
            }
        }
        let mut bytes = Vec::new();
        bytes
            .try_reserve_exact(size)
            .map_err(|_| BpeTokenizerError::Capacity("decoded byte allocation failed"))?;
        for &token_id in tokens {
            bytes.extend_from_slice(self.token_bytes(token_id).expect("validated content token"));
        }
        Ok(bytes)
    }
}

fn strict_utf8(bytes: Vec<u8>) -> Result<String, BpeTokenizerError> {
    String::from_utf8(bytes).map_err(|error| {
        let utf8 = error.utf8_error();
        BpeTokenizerError::InvalidUtf8 {
            valid_up_to: utf8.valid_up_to(),
            error_len: utf8.error_len(),
        }
    })
}

/// Stable, typed diagnostics for tokenizer construction and decoding.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum BpeTokenizerError {
    /// A caller bound or fallible allocation refused an expansion or frame.
    Capacity(&'static str),
    /// The requested final namespace cannot be represented by `u32` IDs.
    LayoutOverflow { merge_count: usize },
    /// A frozen pair refers to a token unavailable at that rank.
    UnknownMergeOperand { rank: usize, token_id: u32 },
    /// A pair appears at more than one rank.
    DuplicateMergePair { rank: usize, left: u32, right: u32 },
    /// BOS or EOS was passed to content-only decoding.
    ControlTokenInContent { position: usize, token_id: u32 },
    /// A token ID has no byte expansion in this tokenizer.
    UnknownToken { position: usize, token_id: u32 },
    /// A document cannot contain both required endpoint controls.
    DocumentTooShort { length: usize },
    /// The first document token is not BOS.
    ExpectedBos { found: u32 },
    /// The final document token is not EOS.
    ExpectedEos { found: u32 },
    /// A document control appeared between its endpoints.
    InteriorControlToken { position: usize, token_id: u32 },
    /// Exact bytes were recovered but are not a valid UTF-8 string.
    InvalidUtf8 {
        valid_up_to: usize,
        error_len: Option<usize>,
    },
}

impl fmt::Display for BpeTokenizerError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Capacity(reason) => formatter.write_str(reason),
            Self::LayoutOverflow { merge_count } => write!(
                formatter,
                "{merge_count} merge ranks do not fit tokenizer layout version {TOKENIZER_LAYOUT_VERSION}"
            ),
            Self::UnknownMergeOperand { rank, token_id } => write!(
                formatter,
                "merge rank {rank} references unavailable training token {token_id}"
            ),
            Self::DuplicateMergePair { rank, left, right } => write!(
                formatter,
                "merge rank {rank} repeats training pair ({left},{right})"
            ),
            Self::ControlTokenInContent { position, token_id } => write!(
                formatter,
                "control token {token_id} is not allowed in content at position {position}"
            ),
            Self::UnknownToken { position, token_id } => write!(
                formatter,
                "token {token_id} at position {position} is outside this tokenizer vocabulary"
            ),
            Self::DocumentTooShort { length } => write!(
                formatter,
                "document token sequence of length {length} cannot contain BOS and EOS"
            ),
            Self::ExpectedBos { found } => {
                write!(
                    formatter,
                    "expected BOS token 0, found {found} at position 0"
                )
            }
            Self::ExpectedEos { found } => write!(
                formatter,
                "expected EOS token 1, found {found} at the final position"
            ),
            Self::InteriorControlToken { position, token_id } => write!(
                formatter,
                "document control token {token_id} is not allowed at position {position}"
            ),
            Self::InvalidUtf8 { valid_up_to, .. } => write!(
                formatter,
                "decoded bytes are not valid UTF-8 at byte {valid_up_to}"
            ),
        }
    }
}

impl Error for BpeTokenizerError {}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::corpus::{Corpus, SplitManifest};
    use crate::tokenizer::bpe_trainer::BpeTrainer;

    const CORPUS_JSON: &str = include_str!("../../../../data/tiny-bilingual-corpus.json");
    const SPLIT_MANIFEST: &str = include_str!("../../../../data/splits.json");

    fn canonical_training() -> BpeTraining {
        let corpus = Corpus::from_json(CORPUS_JSON).expect("fixture corpus");
        let manifest = SplitManifest::from_json(SPLIT_MANIFEST).expect("fixture manifest");
        let partitions = manifest.partition(&corpus).expect("valid fixture split");
        BpeTrainer::new(8)
            .train(&partitions)
            .expect("eight frozen ranks")
    }

    fn chained_training() -> BpeTraining {
        const CORPUS: &str = r#"[
  {"id":"train-one","language":"en","provenance_group":"train-one","text":"aaaa"},
  {"id":"validation-one","language":"en","provenance_group":"validation-one","text":"bbbb"},
  {"id":"test-one","language":"en","provenance_group":"test-one","text":"cccc"}
]"#;
        let corpus = Corpus::from_json(CORPUS).expect("chained-merge corpus");
        let manifest_json = format!(
            r#"{{"schema_version":1,"corpus_checksum":"{}","strategy":"fixed-paired-document-holdout-v1","train":["train-one"],"validation":["validation-one"],"test":["test-one"]}}"#,
            corpus.checksum()
        );
        let manifest = SplitManifest::from_json(&manifest_json).expect("chained-merge manifest");
        let partitions = manifest
            .partition(&corpus)
            .expect("valid chained-merge split");
        BpeTrainer::new(2)
            .train(&partitions)
            .expect("two chained ranks")
    }

    fn canonical_tokenizer() -> BpeTokenizer {
        let training = canonical_training();
        BpeTokenizer::from_training(&training).expect("valid frozen tokenizer")
    }

    #[test]
    fn copies_the_sealed_training_result_into_independent_storage() {
        let training = canonical_training();
        let pairs = training
            .rules()
            .iter()
            .map(|rule| rule.pair())
            .collect::<Vec<_>>();
        let expected = BpeTokenizer::from_merge_pairs(&pairs).expect("valid raw pair table");
        let tokenizer = BpeTokenizer::from_training(&training).expect("valid frozen tokenizer");

        assert_eq!(tokenizer, expected);
        drop(training);
        assert_eq!(
            tokenizer.decode_content_utf8(&[258, 178]),
            Ok(" а".to_owned())
        );
    }

    #[test]
    fn copies_chained_sealed_expansions_without_reconstruction() {
        let training = chained_training();
        assert_eq!(
            training
                .rules()
                .iter()
                .map(|rule| rule.pair())
                .collect::<Vec<_>>(),
            [TokenPair::new(97, 97), TokenPair::new(256, 256)]
        );
        assert_eq!(training.token_bytes(257), Some(b"aaaa".as_slice()));

        let pairs = training
            .rules()
            .iter()
            .map(|rule| rule.pair())
            .collect::<Vec<_>>();
        let reconstructed =
            BpeTokenizer::from_merge_pairs(&pairs).expect("valid chained raw pair table");
        let tokenizer = BpeTokenizer::from_training(&training).expect("valid chained training");

        assert_eq!(tokenizer, reconstructed);
        drop(training);
        assert_eq!(tokenizer.token_bytes(259), Some(b"aaaa".as_slice()));
        assert_eq!(tokenizer.encode_content(b"aaaa"), [259]);
    }

    #[test]
    fn freezes_layout_ranges_and_shifted_rules() {
        let tokenizer = canonical_tokenizer();
        let layout = tokenizer.layout();
        assert_eq!(layout.version(), 1);
        assert_eq!(BOS_TOKEN_ID, 0);
        assert_eq!(EOS_TOKEN_ID, 1);
        assert_eq!(layout.byte_token_id(0), 2);
        assert_eq!(layout.byte_token_id(255), 257);
        assert_eq!(layout.merge_token_id(0), Some(258));
        assert_eq!(layout.merge_token_id(7), Some(265));
        assert_eq!(layout.merge_token_id(8), None);
        assert_eq!(layout.vocabulary_size(), 266);

        for rule in tokenizer.merge_rules() {
            assert_eq!(rule.training_token_id(), 256 + rule.rank() as u32);
            assert_eq!(rule.content_token_id(), 258 + rule.rank() as u32);
            assert_eq!(
                rule.content_pair(),
                TokenPair::new(
                    rule.training_pair().left() + CONTENT_ID_OFFSET,
                    rule.training_pair().right() + CONTENT_ID_OFFSET
                )
            );
            assert!(rule.content_pair().left() >= FIRST_BYTE_TOKEN_ID);
            assert!(rule.content_pair().right() >= FIRST_BYTE_TOKEN_ID);
        }
        assert!(tokenizer.token_bytes(BOS_TOKEN_ID).is_none());
        assert!(tokenizer.token_bytes(EOS_TOKEN_ID).is_none());
    }

    #[test]
    fn applies_chained_ranks_in_order() {
        let tokenizer =
            BpeTokenizer::from_merge_pairs(&[TokenPair::new(97, 98), TokenPair::new(256, 99)])
                .expect("valid chained ranks");
        let trace = tokenizer.encode_content_with_trace(b"abc");
        assert_eq!(trace.initial_tokens(), [99, 100, 101]);
        assert_eq!(
            trace
                .applications()
                .iter()
                .map(BpeMergeApplication::rank)
                .collect::<Vec<_>>(),
            [0, 1]
        );
        assert_eq!(trace.applications()[0].before(), [99, 100, 101]);
        assert_eq!(trace.applications()[0].after(), [258, 101]);
        assert_eq!(trace.applications()[1].after(), [259]);
        assert_eq!(trace.content_tokens(), [259]);
        assert_eq!(
            tokenizer.decode_content(trace.content_tokens()),
            Ok(b"abc".to_vec())
        );
    }

    #[test]
    fn lean_and_traced_encoding_return_the_same_tokens() {
        fn assert_equivalent(tokenizer: &BpeTokenizer, inputs: &[&[u8]]) {
            for input in inputs {
                assert_eq!(
                    tokenizer.encode_content(input),
                    tokenizer.encode_content_with_trace(input).content_tokens(),
                    "lean and traced encoding differ for bytes {input:?}"
                );
            }
        }

        let canonical = canonical_tokenizer();
        assert_equivalent(
            &canonical,
            &[
                b"",
                b"z",
                " а bee ".as_bytes(),
                b"aaaaa",
                &[0xff, 0xfe, 0x00, 0xe2, 0x82],
            ],
        );

        let chained =
            BpeTokenizer::from_merge_pairs(&[TokenPair::new(97, 98), TokenPair::new(256, 99)])
                .expect("valid chained ranks");
        assert_equivalent(&chained, &[b"abc", b"zabcabc"]);

        let repeated =
            BpeTokenizer::from_merge_pairs(&[TokenPair::new(97, 97)]).expect("valid repeated pair");
        assert_equivalent(&repeated, &[b"aaaaa", b"baaaab"]);

        let byte_only = BpeTokenizer::from_merge_pairs(&[]).expect("zero ranks are valid");
        assert_equivalent(&byte_only, &[b"", b"ASCII", &[0, 255]]);
    }

    #[test]
    fn rejects_overflow_unknown_operands_and_duplicate_pairs() {
        if let Ok(namespace_extent) = usize::try_from(u64::from(u32::MAX) + 1) {
            let maximum_merge_count = namespace_extent - FIRST_MERGE_TOKEN_ID as usize;
            let maximum = TokenizerLayout::new(maximum_merge_count).expect("u32 boundary fits");
            assert_eq!(
                maximum.merge_token_id(maximum_merge_count - 1),
                Some(u32::MAX)
            );
            assert_eq!(
                TokenizerLayout::new(maximum_merge_count + 1),
                Err(BpeTokenizerError::LayoutOverflow {
                    merge_count: maximum_merge_count + 1
                })
            );
        }
        assert!(matches!(
            TokenizerLayout::new(usize::MAX),
            Err(BpeTokenizerError::LayoutOverflow { .. })
        ));
        assert_eq!(
            BpeTokenizer::from_merge_pairs(&[TokenPair::new(256, 97)]),
            Err(BpeTokenizerError::UnknownMergeOperand {
                rank: 0,
                token_id: 256
            })
        );
        assert_eq!(
            BpeTokenizer::from_merge_pairs(&[TokenPair::new(97, 98), TokenPair::new(97, 98)]),
            Err(BpeTokenizerError::DuplicateMergePair {
                rank: 1,
                left: 97,
                right: 98
            })
        );
    }

    #[test]
    fn matches_exact_ascii_cyrillic_and_unseen_examples() {
        let tokenizer = canonical_tokenizer();
        assert_eq!(tokenizer.encode_utf8("bee "), [100, 103, 265]);
        assert_eq!(tokenizer.encode_utf8(" а"), [258, 178]);
        assert_eq!(tokenizer.encode_utf8("река"), [264, 261, 210, 188, 259]);
        assert_eq!(tokenizer.encode_utf8("🦀"), [242, 161, 168, 130]);
        assert_eq!(
            tokenizer.decode_content_utf8(&[100, 103, 265]),
            Ok("bee ".to_owned())
        );
        assert_eq!(
            tokenizer.decode_content_utf8(&[258, 178]),
            Ok(" а".to_owned())
        );
    }

    #[test]
    fn round_trips_every_byte_and_mixed_content() {
        let tokenizer = canonical_tokenizer();
        let all_bytes = (u8::MIN..=u8::MAX).collect::<Vec<_>>();
        let mixed = b"line one\n\0Cyrillic: \xd1\x82\n";
        for bytes in [all_bytes.as_slice(), mixed.as_slice(), b"", b"ASCII"] {
            let content = tokenizer.encode_content(bytes);
            assert_eq!(tokenizer.decode_content(&content), Ok(bytes.to_vec()));
            let document = tokenizer.encode_document(bytes);
            assert_eq!(document.first(), Some(&BOS_TOKEN_ID));
            assert_eq!(document.last(), Some(&EOS_TOKEN_ID));
            assert_eq!(tokenizer.decode_document(&document), Ok(bytes.to_vec()));
        }
        assert_eq!(tokenizer.encode_content(b""), Vec::<u32>::new());
        assert_eq!(tokenizer.encode_document(b""), [0, 1]);

        let byte_only = BpeTokenizer::from_merge_pairs(&[]).expect("zero ranks are valid");
        assert_eq!(byte_only.layout().vocabulary_size(), 258);
        assert_eq!(byte_only.encode_content(&[0, 255]), [2, 257]);
        assert_eq!(byte_only.decode_content(&[2, 257]), Ok(vec![0, 255]));
    }

    #[test]
    fn preserves_malformed_bytes_but_rejects_their_text_view() {
        let tokenizer = canonical_tokenizer();
        let content = tokenizer.encode_content(&[0xff, 0xfe]);
        assert_eq!(content, [257, 256]);
        assert_eq!(tokenizer.decode_content(&content), Ok(vec![0xff, 0xfe]));
        assert_eq!(
            tokenizer.decode_content_utf8(&content),
            Err(BpeTokenizerError::InvalidUtf8 {
                valid_up_to: 0,
                error_len: Some(1)
            })
        );
        let truncated = tokenizer.encode_content(&[0xe2, 0x82]);
        assert_eq!(
            tokenizer.decode_content_utf8(&truncated),
            Err(BpeTokenizerError::InvalidUtf8 {
                valid_up_to: 0,
                error_len: None
            })
        );
    }

    #[test]
    fn distinguishes_exact_decoding_from_canonical_encoding() {
        let tokenizer = canonical_tokenizer();
        let canonical = tokenizer.encode_utf8(" а");
        let noncanonical = [34, 259];
        assert_eq!(canonical, [258, 178]);
        assert_eq!(
            tokenizer.decode_content(&noncanonical),
            tokenizer.decode_content(&canonical)
        );
        let bytes = tokenizer
            .decode_content(&noncanonical)
            .expect("valid byte sequence");
        assert_eq!(tokenizer.encode_content(&bytes), canonical);
        assert_ne!(tokenizer.encode_content(&bytes), noncanonical);
    }

    #[test]
    fn validates_controls_wrappers_and_unknown_ids_strictly() {
        let tokenizer = canonical_tokenizer();
        assert_eq!(
            tokenizer.decode_content(&[100, BOS_TOKEN_ID]),
            Err(BpeTokenizerError::ControlTokenInContent {
                position: 1,
                token_id: BOS_TOKEN_ID
            })
        );
        assert_eq!(
            tokenizer.decode_content(&[EOS_TOKEN_ID]),
            Err(BpeTokenizerError::ControlTokenInContent {
                position: 0,
                token_id: EOS_TOKEN_ID
            })
        );
        assert_eq!(
            tokenizer.decode_content(&[266]),
            Err(BpeTokenizerError::UnknownToken {
                position: 0,
                token_id: 266
            })
        );
        assert_eq!(
            tokenizer.decode_document(&[]),
            Err(BpeTokenizerError::DocumentTooShort { length: 0 })
        );
        assert_eq!(
            tokenizer.decode_document(&[0]),
            Err(BpeTokenizerError::DocumentTooShort { length: 1 })
        );
        assert_eq!(
            tokenizer.decode_document(&[1, 100, 1]),
            Err(BpeTokenizerError::ExpectedBos { found: 1 })
        );
        assert_eq!(
            tokenizer.decode_document(&[0, 100, 0]),
            Err(BpeTokenizerError::ExpectedEos { found: 0 })
        );
        assert_eq!(
            tokenizer.decode_document(&[0, 100, 0, 1]),
            Err(BpeTokenizerError::InteriorControlToken {
                position: 2,
                token_id: 0
            })
        );
        assert_eq!(
            tokenizer.decode_document(&[0, 1, 1]),
            Err(BpeTokenizerError::InteriorControlToken {
                position: 1,
                token_id: 1
            })
        );
        assert_eq!(
            tokenizer.decode_document(&[0, 266, 1]),
            Err(BpeTokenizerError::UnknownToken {
                position: 1,
                token_id: 266
            })
        );
    }

    #[test]
    fn is_deterministic_and_never_merges_controls() {
        let tokenizer = canonical_tokenizer();
        let first = tokenizer.encode_content_with_trace(" а bee ".as_bytes());
        let second = tokenizer.encode_content_with_trace(" а bee ".as_bytes());
        assert_eq!(first, second);
        assert!(first.content_tokens().iter().all(|token| *token >= 2));
        assert!(
            tokenizer.merge_rules().iter().all(|rule| {
                rule.content_pair().left() >= 2 && rule.content_pair().right() >= 2
            })
        );
        let mut expected_document = vec![BOS_TOKEN_ID];
        expected_document.extend_from_slice(first.content_tokens());
        expected_document.push(EOS_TOKEN_ID);
        assert_eq!(tokenizer.encode_utf8_document(" а bee "), expected_document);
    }
}

//! Deterministic byte-pair merge learning over training documents only.
//!
//! The original scalar path uses training-space byte IDs `0..=255`, then
//! merge IDs `256 + rank`. The existing BpeTokenizer maps them into its
//! content namespace, reserving document controls. The prepared-document path
//! works directly with that content layout and emits artifact metadata; it
//! adds no separate vocabulary or decoder.

use std::collections::BTreeMap;
use std::error::Error;
use std::fmt;

use crate::corpus::CorpusPartitions;

pub use super::incremental::{
    PairCount, RoundTrace, TrainingMetrics, TrainingResult as PreparedBpeTraining, WeightedBytes,
    weighted_input_sha256,
};

/// Number of one-byte symbols present before any merge is learned.
pub const BYTE_TOKEN_COUNT: u32 = 256;

/// A numeric adjacent-token candidate.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct TokenPair {
    left: u32,
    right: u32,
}

impl TokenPair {
    /// Creates a candidate from its left and right token IDs.
    pub const fn new(left: u32, right: u32) -> Self {
        Self { left, right }
    }

    /// Returns the left token ID.
    pub const fn left(self) -> u32 {
        self.left
    }

    /// Returns the right token ID.
    pub const fn right(self) -> u32 {
        self.right
    }
}

/// One frozen BPE operation in increasing rank order.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MergeRule {
    rank: usize,
    pair: TokenPair,
    token_id: u32,
    candidate_count: usize,
    replacement_count: usize,
}

impl MergeRule {
    /// Returns the zero-based order in which the rule was learned.
    pub const fn rank(&self) -> usize {
        self.rank
    }

    /// Returns the pair selected during this round.
    pub const fn pair(&self) -> TokenPair {
        self.pair
    }

    /// Returns the new training-space token ID assigned to the merged bytes.
    pub const fn token_id(&self) -> u32 {
        self.token_id
    }

    /// Returns the overlapping pair count used to rank the candidate.
    pub const fn candidate_count(&self) -> usize {
        self.candidate_count
    }

    /// Returns the non-overlapping occurrences replaced in this round.
    pub const fn replacement_count(&self) -> usize {
        self.replacement_count
    }
}

/// The learned ranks, vocabulary expansions, and final training sequences.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BpeTraining {
    requested_merges: usize,
    training_document_ids: Vec<String>,
    rules: Vec<MergeRule>,
    vocabulary: Vec<Vec<u8>>,
    final_sequences: Vec<Vec<u32>>,
}

impl BpeTraining {
    /// Returns the configured maximum number of rounds.
    pub const fn requested_merges(&self) -> usize {
        self.requested_merges
    }

    /// Returns the exact source IDs that supplied pair statistics.
    pub fn training_document_ids(&self) -> &[String] {
        &self.training_document_ids
    }

    /// Returns rules in frozen application order.
    pub fn rules(&self) -> &[MergeRule] {
        &self.rules
    }

    /// Returns each training document's final token sequence in source order.
    pub fn final_sequences(&self) -> &[Vec<u32>] {
        &self.final_sequences
    }

    /// Returns the 256 byte symbols plus one symbol per successful rule.
    pub fn vocabulary_size(&self) -> usize {
        self.vocabulary.len()
    }

    /// Expands one training-space token ID to the bytes it represents.
    pub fn token_bytes(&self, token_id: u32) -> Option<&[u8]> {
        usize::try_from(token_id)
            .ok()
            .and_then(|index| self.vocabulary.get(index))
            .map(Vec::as_slice)
    }

    /// Borrows the complete validated vocabulary for a crate-owned tokenizer.
    pub(crate) fn vocabulary(&self) -> &[Vec<u8>] {
        &self.vocabulary
    }
}

/// A deterministic trainer with a fixed upper bound on merge rounds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BpeTrainer {
    max_merges: usize,
}

impl BpeTrainer {
    /// Creates a trainer. Zero is a valid request and learns no rules.
    pub const fn new(max_merges: usize) -> Self {
        Self { max_merges }
    }

    /// Use the existing scalar learning loop on explicit, already-owned byte fixtures.
    /// This adapter supplies no real-corpus split or provenance approval.
    pub fn train_byte_fixture(
        self,
        documents: &[Vec<u8>],
    ) -> Result<BpeTraining, BpeTrainingError> {
        self.validate_merge_budget()?;
        let ids = (0..documents.len())
            .map(|index| format!("fixture-{index}"))
            .collect();
        let sequences = documents
            .iter()
            .map(|bytes| bytes_to_tokens(bytes))
            .collect();
        learn_from_token_sequences(self.max_merges, ids, sequences)
    }

    // region:bounded-prepared-training
    /// Extend this trainer to bounded, selected prepared documents with local pair updates.
    pub fn train_prepared<R: std::io::Read>(
        self,
        reader: R,
        read_limits: crate::data::prepared_corpus::ReadLimits,
        binding: super::policy::TrainingBinding,
        policy: super::policy::TokenizerPolicy,
        limits: super::policy::TokenizerLimits,
        trace: bool,
    ) -> Result<PreparedBpeTraining, super::policy::TokenizerError> {
        if self.max_merges != policy.merge_count {
            return Err(super::policy::TokenizerError::Policy(
                "trainer and serialized merge budgets differ",
            ));
        }
        super::incremental::train_prepared(reader, read_limits, binding, policy, limits, trace)
    }
    // endregion:bounded-prepared-training

    /// Bounded weighted fixtures test counts without allocating every repeated copy.
    pub fn train_weighted_fixture(
        self,
        documents: &[WeightedBytes],
        binding: super::policy::TrainingBinding,
        policy: super::policy::TokenizerPolicy,
        limits: super::policy::TokenizerLimits,
        trace: bool,
    ) -> Result<PreparedBpeTraining, super::policy::TokenizerError> {
        if self.max_merges != policy.merge_count {
            return Err(super::policy::TokenizerError::Policy(
                "trainer and serialized merge budgets differ",
            ));
        }
        super::incremental::train_weighted_fixture(documents, binding, policy, limits, trace)
    }

    fn validate_merge_budget(self) -> Result<(), BpeTrainingError> {
        let available_merge_ids = u128::from(u32::MAX) - u128::from(u8::MAX);
        if self.max_merges as u128 > available_merge_ids {
            return Err(BpeTrainingError::new(
                "requested merge count exceeds the u32 token-ID space",
            ));
        }
        Ok(())
    }

    /// Learns only from the partition object's training view.
    // region:deterministic-training
    pub fn train(self, partitions: &CorpusPartitions<'_>) -> Result<BpeTraining, BpeTrainingError> {
        self.validate_merge_budget()?;
        let training_documents = partitions.training_documents();
        let document_ids = training_documents
            .iter()
            .map(|document| document.id().to_owned())
            .collect::<Vec<_>>();
        let sequences = training_documents
            .iter()
            .map(|document| bytes_to_tokens(document.text().as_bytes()))
            .collect::<Vec<_>>();

        learn_from_token_sequences(self.max_merges, document_ids, sequences)
    }
    // endregion:deterministic-training
}

/// Counts adjacent pairs independently inside every supplied token sequence.
// region:overlapping-pair-counting
pub fn count_adjacent_pairs(sequences: &[Vec<u32>]) -> BTreeMap<TokenPair, usize> {
    let mut counts = BTreeMap::new();
    for sequence in sequences {
        for window in sequence.windows(2) {
            let pair = TokenPair::new(window[0], window[1]);
            *counts.entry(pair).or_insert(0) += 1;
        }
    }
    counts
}

/// Selects the greatest count, breaking ties by the smallest `(left, right)` IDs.
pub fn choose_most_frequent_pair(
    counts: &BTreeMap<TokenPair, usize>,
) -> Option<(TokenPair, usize)> {
    let mut winner = None;
    for (&pair, &count) in counts {
        match winner {
            None => winner = Some((pair, count)),
            Some((_, best_count)) if count > best_count => winner = Some((pair, count)),
            Some(_) => {}
        }
    }
    winner
}
// endregion:overlapping-pair-counting

/// Replaces matches from left to right, so one input token is consumed at most once.
// region:non-overlapping-replacement
pub fn replace_pair_left_to_right(
    sequence: &[u32],
    pair: TokenPair,
    replacement: u32,
) -> (Vec<u32>, usize) {
    let mut output = Vec::with_capacity(sequence.len());
    let mut replacements = 0;
    let mut index = 0;

    while index < sequence.len() {
        if index + 1 < sequence.len()
            && sequence[index] == pair.left
            && sequence[index + 1] == pair.right
        {
            output.push(replacement);
            replacements += 1;
            index += 2;
        } else {
            output.push(sequence[index]);
            index += 1;
        }
    }

    (output, replacements)
}
// endregion:non-overlapping-replacement

/// Converts raw bytes to the initial numeric vocabulary.
pub fn bytes_to_tokens(bytes: &[u8]) -> Vec<u32> {
    bytes.iter().map(|byte| u32::from(*byte)).collect()
}

fn learn_from_token_sequences(
    max_merges: usize,
    document_ids: Vec<String>,
    mut sequences: Vec<Vec<u32>>,
) -> Result<BpeTraining, BpeTrainingError> {
    let mut vocabulary = (u8::MIN..=u8::MAX)
        .map(|byte| vec![byte])
        .collect::<Vec<_>>();
    let mut rules = Vec::new();

    for rank in 0..max_merges {
        let counts = count_adjacent_pairs(&sequences);
        let Some((pair, candidate_count)) = choose_most_frequent_pair(&counts) else {
            break;
        };

        let token_id = u32::try_from(vocabulary.len()).map_err(|_| {
            BpeTrainingError::new("learned vocabulary exceeds the u32 token-ID space")
        })?;
        let left_bytes = vocabulary
            .get(usize::try_from(pair.left).unwrap_or(usize::MAX))
            .ok_or_else(|| BpeTrainingError::new("pair contains an unknown left token ID"))?;
        let right_bytes = vocabulary
            .get(usize::try_from(pair.right).unwrap_or(usize::MAX))
            .ok_or_else(|| BpeTrainingError::new("pair contains an unknown right token ID"))?;
        let mut merged_bytes = Vec::with_capacity(left_bytes.len() + right_bytes.len());
        merged_bytes.extend_from_slice(left_bytes);
        merged_bytes.extend_from_slice(right_bytes);

        let mut replacement_count = 0;
        for sequence in &mut sequences {
            let (replaced, count) = replace_pair_left_to_right(sequence, pair, token_id);
            *sequence = replaced;
            replacement_count += count;
        }
        if replacement_count == 0 {
            return Err(BpeTrainingError::new(
                "selected pair had no replaceable occurrence",
            ));
        }

        vocabulary.push(merged_bytes);
        rules.push(MergeRule {
            rank,
            pair,
            token_id,
            candidate_count,
            replacement_count,
        });
    }

    Ok(BpeTraining {
        requested_merges: max_merges,
        training_document_ids: document_ids,
        rules,
        vocabulary,
        final_sequences: sequences,
    })
}

/// A stable, dependency-free trainer diagnostic.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BpeTrainingError {
    message: String,
}

impl BpeTrainingError {
    fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }

    /// Returns the stable diagnostic text.
    pub fn message(&self) -> &str {
        &self.message
    }
}

impl fmt::Display for BpeTrainingError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.message)
    }
}

impl Error for BpeTrainingError {}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::corpus::{Corpus, Partition, SplitManifest};

    const CORPUS_JSON: &str = include_str!("../../../../data/tiny-bilingual-corpus.json");
    const SPLIT_MANIFEST: &str = include_str!("../../../../data/splits.json");

    #[test]
    fn counts_overlaps_but_replaces_without_overlap() {
        let sequences = vec![bytes_to_tokens(b"aaa")];
        let pair = TokenPair::new(97, 97);
        assert_eq!(count_adjacent_pairs(&sequences).get(&pair), Some(&2));

        let (replaced, count) = replace_pair_left_to_right(&sequences[0], pair, 256);
        assert_eq!(replaced, [256, 97]);
        assert_eq!(count, 1);
    }

    #[test]
    fn resolves_count_ties_by_numeric_pair_order() {
        let sequences = vec![vec![98, 97], vec![97, 98]];
        let counts = count_adjacent_pairs(&sequences);
        assert_eq!(counts.get(&TokenPair::new(97, 98)), Some(&1));
        assert_eq!(counts.get(&TokenPair::new(98, 97)), Some(&1));
        assert_eq!(
            choose_most_frequent_pair(&counts),
            Some((TokenPair::new(97, 98), 1))
        );
    }

    #[test]
    fn never_counts_across_document_boundaries() {
        assert!(count_adjacent_pairs(&[vec![1], vec![2]]).is_empty());
        assert_eq!(
            count_adjacent_pairs(&[vec![1, 2]])
                .get(&TokenPair::new(1, 2))
                .copied(),
            Some(1)
        );
    }

    #[test]
    fn zero_merges_preserves_initial_training_sequences() {
        let corpus = Corpus::from_json(CORPUS_JSON).expect("fixture corpus");
        let manifest = SplitManifest::from_json(SPLIT_MANIFEST).expect("fixture manifest");
        let partitions = manifest.partition(&corpus).expect("valid fixture split");
        let training = BpeTrainer::new(0).train(&partitions).expect("zero rounds");

        assert!(training.rules().is_empty());
        assert_eq!(training.training_document_ids().len(), 8);
        assert_eq!(
            training.final_sequences()[0],
            bytes_to_tokens(partitions.documents(Partition::Train)[0].text().as_bytes())
        );
    }

    #[test]
    fn learns_from_training_partition_only_and_is_reproducible() {
        let corpus = Corpus::from_json(CORPUS_JSON).expect("fixture corpus");
        let manifest = SplitManifest::from_json(SPLIT_MANIFEST).expect("fixture manifest");
        let partitions = manifest.partition(&corpus).expect("valid fixture split");

        let first = BpeTrainer::new(8)
            .train(&partitions)
            .expect("training succeeds");
        let second = BpeTrainer::new(8)
            .train(&partitions)
            .expect("training repeats");

        assert_eq!(first, second);
        assert_eq!(first.rules().len(), 8);
        assert_eq!(first.vocabulary_size(), 264);
        assert_eq!(
            first.training_document_ids(),
            partitions.document_ids(Partition::Train)
        );
        assert!(first.training_document_ids().iter().all(|id| {
            !partitions
                .document_ids(Partition::Validation)
                .contains(&id.as_str())
                && !partitions
                    .document_ids(Partition::Test)
                    .contains(&id.as_str())
        }));
        for rule in first.rules() {
            assert_eq!(rule.token_id(), BYTE_TOKEN_COUNT + rule.rank() as u32);
            assert!(rule.candidate_count() >= rule.replacement_count());
            assert!(rule.replacement_count() > 0);
            assert!(first.token_bytes(rule.token_id()).is_some());
        }
        let expected = [
            (TokenPair::new(32, 208), 81, &[0x20, 0xd0][..]),
            (TokenPair::new(208, 176), 62, &[0xd0, 0xb0][..]),
            (TokenPair::new(209, 130), 57, &[0xd1, 0x82][..]),
            (TokenPair::new(208, 181), 56, &[0xd0, 0xb5][..]),
            (TokenPair::new(208, 190), 49, &[0xd0, 0xbe][..]),
            (TokenPair::new(208, 184), 38, &[0xd0, 0xb8][..]),
            (TokenPair::new(209, 128), 36, &[0xd1, 0x80][..]),
            (TokenPair::new(101, 32), 35, &[0x65, 0x20][..]),
        ];
        for (rule, (pair, count, bytes)) in first.rules().iter().zip(expected) {
            assert_eq!(rule.pair(), pair);
            assert_eq!(rule.candidate_count(), count);
            assert_eq!(first.token_bytes(rule.token_id()), Some(bytes));
        }
        let unique_pairs = first
            .rules()
            .iter()
            .map(MergeRule::pair)
            .collect::<std::collections::BTreeSet<_>>();
        assert_eq!(unique_pairs.len(), first.rules().len());
    }

    #[test]
    fn rejects_more_merges_than_u32_can_name() {
        let corpus = Corpus::from_json(CORPUS_JSON).expect("fixture corpus");
        let manifest = SplitManifest::from_json(SPLIT_MANIFEST).expect("fixture manifest");
        let partitions = manifest.partition(&corpus).expect("valid fixture split");
        let error = BpeTrainer::new(usize::MAX)
            .train(&partitions)
            .expect_err("impossible token space must fail");
        assert_eq!(
            error.message(),
            "requested merge count exceeds the u32 token-ID space"
        );
    }
}

// Ranked BPE application with checked live adjacency and structural controls.

use super::bpe::BpeTokenizer;
use super::bpe_trainer::TokenPair;
use super::policy::{TokenizerError, TokenizerLimits};
use std::cmp::Reverse;
use std::collections::{BTreeMap, BinaryHeap};
use std::io::Read;

#[derive(Clone, Debug)]
struct Node {
    token: u32,
    previous: Option<usize>,
    next: Option<usize>,
    version: u64,
    alive: bool,
}

// Tuple order: lowest learned rank, then leftmost original byte position.
type Candidate = Reverse<(usize, usize, usize, u64, u64)>;

fn candidate(
    nodes: &[Node],
    index: usize,
    ranks: &BTreeMap<TokenPair, (usize, u32)>,
) -> Option<Candidate> {
    let left = nodes.get(index)?;
    if !left.alive {
        return None;
    }
    let right_index = left.next?;
    let right = &nodes[right_index];
    if !right.alive {
        return None;
    }
    let &(rank, _) = ranks.get(&TokenPair::new(left.token, right.token))?;
    Some(Reverse((
        rank,
        index,
        right_index,
        left.version,
        right.version,
    )))
}

fn enqueue(
    heap: &mut BinaryHeap<Candidate>,
    nodes: &[Node],
    index: usize,
    ranks: &BTreeMap<TokenPair, (usize, u32)>,
    limits: TokenizerLimits,
) -> Result<(), TokenizerError> {
    let Some(entry) = candidate(nodes, index, ranks) else {
        return Ok(());
    };
    if heap.len() == limits.max_heap_entries {
        heap.clear();
        for index in 0..nodes.len() {
            if let Some(current) = candidate(nodes, index, ranks) {
                if heap.len() == limits.max_heap_entries {
                    return Err(TokenizerError::Resource(
                        "live encoding queue exceeds capacity",
                    ));
                }
                heap.try_reserve_exact(1)
                    .map_err(|_| TokenizerError::Resource("encoding queue allocation failed"))?;
                heap.push(current);
            }
        }
        // The rebuilt queue already contains entry if it is still live.
    } else {
        heap.try_reserve_exact(1)
            .map_err(|_| TokenizerError::Resource("encoding queue allocation failed"))?;
        heap.push(entry);
    }
    Ok(())
}

/// All inputs are content bytes. Controls can only be inserted by encode_document.
pub(super) fn encode_bytes(
    tokenizer: &BpeTokenizer,
    bytes: &[u8],
    limits: TokenizerLimits,
) -> Result<Vec<u32>, TokenizerError> {
    limits.validate()?;
    if bytes.len() > limits.max_nodes {
        return Err(TokenizerError::Resource("encoding node capacity exceeded"));
    }
    if tokenizer.merge_rules().len() > limits.max_pair_types {
        return Err(TokenizerError::Resource("encoding rank capacity exceeded"));
    }
    let ranks = tokenizer
        .merge_rules()
        .iter()
        .map(|rule| (rule.content_pair(), (rule.rank(), rule.content_token_id())))
        .collect::<BTreeMap<_, _>>();
    let mut nodes = Vec::new();
    nodes
        .try_reserve_exact(bytes.len())
        .map_err(|_| TokenizerError::Resource("encoding node allocation failed"))?;
    for (index, &byte) in bytes.iter().enumerate() {
        nodes.push(Node {
            token: tokenizer.layout().byte_token_id(byte),
            previous: (index > 0).then(|| index - 1),
            next: (index + 1 < bytes.len()).then_some(index + 1),
            version: 0,
            alive: true,
        });
    }
    let mut heap = BinaryHeap::new();
    for index in 0..nodes.len() {
        enqueue(&mut heap, &nodes, index, &ranks, limits)?;
    }
    // region:ranked-live-encoding
    while let Some(entry) = heap.pop() {
        let Reverse((rank, left, right, _, _)) = entry;
        if candidate(&nodes, left, &ranks) != Some(entry) {
            continue;
        }
        let output = tokenizer.merge_rules()[rank].content_token_id();
        let previous = nodes[left].previous;
        let next = nodes[right].next;
        nodes[left].token = output;
        nodes[left].next = next;
        nodes[left].version = nodes[left]
            .version
            .checked_add(1)
            .ok_or(TokenizerError::Overflow)?;
        nodes[right].alive = false;
        if let Some(index) = next {
            nodes[index].previous = Some(left);
        }
        if let Some(index) = previous {
            enqueue(&mut heap, &nodes, index, &ranks, limits)?;
        }
        enqueue(&mut heap, &nodes, left, &ranks, limits)?;
    }
    // endregion:ranked-live-encoding
    let mut output = Vec::new();
    output
        .try_reserve_exact(nodes.len())
        .map_err(|_| TokenizerError::Resource("encoding output allocation failed"))?;
    let mut index = (!nodes.is_empty()).then_some(0);
    while let Some(current) = index {
        output.push(nodes[current].token);
        index = nodes[current].next;
    }
    Ok(output)
}

/// Read boundaries never become BPE boundaries: read one bounded whole document
/// before encoding. Call separately for each document; do not concatenate roles.
pub(super) fn encode_reader<R: Read>(
    tokenizer: &BpeTokenizer,
    reader: R,
    limits: TokenizerLimits,
) -> Result<Vec<u32>, TokenizerError> {
    limits.validate()?;
    let cap = limits
        .max_nodes
        .checked_add(1)
        .ok_or(TokenizerError::Overflow)?;
    let mut bytes = Vec::new();
    reader
        .take(cap as u64)
        .read_to_end(&mut bytes)
        .map_err(|e| TokenizerError::Input(e.to_string()))?;
    if bytes.len() > limits.max_nodes {
        return Err(TokenizerError::Resource(
            "encoding input exceeds document capacity",
        ));
    }
    encode_bytes(tokenizer, &bytes, limits)
}

// Bounded ingestion and incremental pair statistics for deterministic byte BPE.
// Input text is released after ingestion. Token-node slots remain in memory;
// this is not an external-memory trainer and makes no full-corpus speed claim.

use super::artifact::{ArtifactMerge, EfficiencyCounters, TokenizerArtifact};
use super::bpe::{TOKENIZER_LAYOUT_VERSION, TokenizerLayout};
use super::policy::{TokenizerError, TokenizerLimits, TokenizerPolicy, TrainingBinding};
use crate::data::prepared_corpus::{PreparedCorpusReader, ReadLimits};
use crate::tokenizer::bpe_trainer::TokenPair;
use serde::Serialize;
use sha2::{Digest, Sha256};
use std::cmp::Reverse;
use std::collections::{BTreeMap, BTreeSet, BinaryHeap};
use std::io::{BufReader, Read};

#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct PairCount {
    pub count: u64,
    pub left: u32,
    pub right: u32,
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct RoundTrace {
    pub counts: Vec<PairCount>,
    pub rule: ArtifactMerge,
    pub sequences: Vec<Vec<u32>>,
}

#[derive(Clone, Copy, Debug, Default, Serialize)]
pub struct TrainingMetrics {
    pub local_edge_updates: u64,
    pub peak_heap_entries: usize,
    pub peak_nodes: usize,
    pub peak_pair_types: usize,
    pub queue_rebuilds: u64,
}

#[derive(Clone, Debug)]
pub struct TrainingResult {
    pub artifact: TokenizerArtifact,
    pub trace: Vec<RoundTrace>,
    pub metrics: TrainingMetrics,
}

/// A byte fixture can represent repeated documents without expanding copies.
#[derive(Clone, Debug)]
pub struct WeightedBytes {
    pub bytes: Vec<u8>,
    pub weight: u64,
}

#[derive(Clone, Debug)]
struct Node {
    token: u32,
    previous: Option<usize>,
    next: Option<usize>,
    document: usize,
    alive: bool,
}

struct PairState {
    count: u64,
    generation: u64,
    occurrences: BTreeSet<usize>,
}

#[derive(Clone, Copy, Eq, PartialEq, Ord, PartialOrd)]
struct QueueEntry {
    count: u64,
    pair: Reverse<TokenPair>,
    generation: u64,
}

struct Engine {
    limits: TokenizerLimits,
    byte_layout: TokenizerLayout,
    nodes: Vec<Node>,
    heads: Vec<Option<usize>>,
    weights: Vec<u64>,
    pairs: BTreeMap<TokenPair, PairState>,
    heap: BinaryHeap<QueueEntry>,
    generation: u64,
    documents: u64,
    input_bytes: u64,
    metrics: TrainingMetrics,
}

impl Engine {
    fn new(limits: TokenizerLimits) -> Result<Self, TokenizerError> {
        limits.validate()?;
        Ok(Self {
            limits,
            byte_layout: TokenizerLayout::new(0)?,
            nodes: Vec::new(),
            heads: Vec::new(),
            weights: Vec::new(),
            pairs: BTreeMap::new(),
            heap: BinaryHeap::new(),
            generation: 0,
            documents: 0,
            input_bytes: 0,
            metrics: TrainingMetrics::default(),
        })
    }

    fn ingest(&mut self, bytes: &[u8], weight: u64) -> Result<(), TokenizerError> {
        if weight == 0 {
            return Err(TokenizerError::Input(
                "document weight must be positive".into(),
            ));
        }
        if self.heads.len() == self.limits.max_documents {
            return Err(TokenizerError::Resource(
                "training document capacity exceeded",
            ));
        }
        let end = self
            .nodes
            .len()
            .checked_add(bytes.len())
            .ok_or(TokenizerError::Overflow)?;
        if end > self.limits.max_nodes {
            return Err(TokenizerError::Resource(
                "live-node arena capacity exceeded",
            ));
        }
        self.nodes
            .try_reserve_exact(bytes.len())
            .map_err(|_| TokenizerError::Resource("node allocation failed"))?;
        self.heads
            .try_reserve_exact(1)
            .map_err(|_| TokenizerError::Resource("document allocation failed"))?;
        self.weights
            .try_reserve_exact(1)
            .map_err(|_| TokenizerError::Resource("weight allocation failed"))?;
        self.documents = self
            .documents
            .checked_add(weight)
            .ok_or(TokenizerError::Overflow)?;
        self.input_bytes = self
            .input_bytes
            .checked_add(
                (bytes.len() as u64)
                    .checked_mul(weight)
                    .ok_or(TokenizerError::Overflow)?,
            )
            .ok_or(TokenizerError::Overflow)?;
        let start = self.nodes.len();
        let document = self.heads.len();
        self.heads.push((!bytes.is_empty()).then_some(start));
        self.weights.push(weight);
        for (offset, &byte) in bytes.iter().enumerate() {
            let index = start + offset;
            self.nodes.push(Node {
                token: self.byte_layout.byte_token_id(byte),
                previous: (offset > 0).then(|| index - 1),
                next: (index + 1 < end).then_some(index + 1),
                document,
                alive: true,
            });
        }
        for index in start..end {
            self.add_edge(index)?;
        }
        self.metrics.peak_nodes = self.metrics.peak_nodes.max(self.nodes.len());
        Ok(())
    }

    fn edge(&self, index: usize) -> Option<TokenPair> {
        let left = self.nodes.get(index)?;
        if !left.alive {
            return None;
        }
        let right = self.nodes.get(left.next?)?;
        if !right.alive {
            return None;
        }
        Some(TokenPair::new(left.token, right.token))
    }

    fn next_generation(&mut self) -> Result<u64, TokenizerError> {
        self.generation = self
            .generation
            .checked_add(1)
            .ok_or(TokenizerError::Overflow)?;
        Ok(self.generation)
    }

    fn add_edge(&mut self, index: usize) -> Result<(), TokenizerError> {
        let Some(pair) = self.edge(index) else {
            return Ok(());
        };
        if !self.pairs.contains_key(&pair) && self.pairs.len() == self.limits.max_pair_types {
            return Err(TokenizerError::Resource("distinct pair capacity exceeded"));
        }
        let weight = self.weights[self.nodes[index].document];
        let generation = self.next_generation()?;
        let state = self.pairs.entry(pair).or_insert_with(|| PairState {
            count: 0,
            generation,
            occurrences: BTreeSet::new(),
        });
        if !state.occurrences.insert(index) {
            return Err(TokenizerError::Invariant("edge counted twice"));
        }
        state.count = state
            .count
            .checked_add(weight)
            .ok_or(TokenizerError::Overflow)?;
        state.generation = generation;
        self.metrics.local_edge_updates = self
            .metrics
            .local_edge_updates
            .checked_add(1)
            .ok_or(TokenizerError::Overflow)?;
        self.metrics.peak_pair_types = self.metrics.peak_pair_types.max(self.pairs.len());
        self.queue(pair)
    }

    fn remove_edge(&mut self, index: usize) -> Result<(), TokenizerError> {
        let Some(pair) = self.edge(index) else {
            return Ok(());
        };
        let weight = self.weights[self.nodes[index].document];
        let generation = self.next_generation()?;
        let state = self
            .pairs
            .get_mut(&pair)
            .ok_or(TokenizerError::Invariant("edge missing from counts"))?;
        if !state.occurrences.remove(&index) {
            return Err(TokenizerError::Invariant("edge removed twice"));
        }
        state.count = state
            .count
            .checked_sub(weight)
            .ok_or(TokenizerError::Invariant("negative pair count"))?;
        state.generation = generation;
        self.metrics.local_edge_updates = self
            .metrics
            .local_edge_updates
            .checked_add(1)
            .ok_or(TokenizerError::Overflow)?;
        if state.count == 0 {
            self.pairs.remove(&pair);
            Ok(())
        } else {
            self.queue(pair)
        }
    }

    fn rebuild_queue(&mut self) -> Result<(), TokenizerError> {
        if self.pairs.len() > self.limits.max_heap_entries {
            return Err(TokenizerError::Resource("live pair queue exceeds capacity"));
        }
        self.heap.clear();
        self.heap
            .try_reserve_exact(self.pairs.len())
            .map_err(|_| TokenizerError::Resource("queue allocation failed"))?;
        for (&pair, state) in &self.pairs {
            self.heap.push(QueueEntry {
                count: state.count,
                pair: Reverse(pair),
                generation: state.generation,
            });
        }
        self.metrics.queue_rebuilds = self
            .metrics
            .queue_rebuilds
            .checked_add(1)
            .ok_or(TokenizerError::Overflow)?;
        self.metrics.peak_heap_entries = self.metrics.peak_heap_entries.max(self.heap.len());
        Ok(())
    }

    fn queue(&mut self, pair: TokenPair) -> Result<(), TokenizerError> {
        // Rebuilding contains the current pair already, so do not add it twice.
        if self.heap.len() == self.limits.max_heap_entries {
            return self.rebuild_queue();
        }
        let state = &self.pairs[&pair];
        self.heap
            .try_reserve_exact(1)
            .map_err(|_| TokenizerError::Resource("queue allocation failed"))?;
        self.heap.push(QueueEntry {
            count: state.count,
            pair: Reverse(pair),
            generation: state.generation,
        });
        self.metrics.peak_heap_entries = self.metrics.peak_heap_entries.max(self.heap.len());
        Ok(())
    }

    // region:incremental-pair-choice
    fn winner(&mut self) -> Option<(TokenPair, u64)> {
        while let Some(entry) = self.heap.pop() {
            let pair = entry.pair.0;
            if self.pairs.get(&pair).is_some_and(|state| {
                state.count == entry.count && state.generation == entry.generation
            }) {
                return Some((pair, entry.count));
            }
        }
        None
    }
    // endregion:incremental-pair-choice

    // region:local-edge-replacement
    fn replace(&mut self, pair: TokenPair, output: u32) -> Result<u64, TokenizerError> {
        let mut replacements = 0u64;
        // Stable indices follow source order; first() gives the leftmost live match.
        while let Some(left) = self
            .pairs
            .get(&pair)
            .and_then(|s| s.occurrences.first())
            .copied()
        {
            if self.edge(left) != Some(pair) {
                return Err(TokenizerError::Invariant("stale live occurrence"));
            }
            let right = self.nodes[left]
                .next
                .ok_or(TokenizerError::Invariant("pair has no right node"))?;
            let previous = self.nodes[left].previous;
            let next = self.nodes[right].next;
            // Three distinct edge starts disappear; adjacent replacements cannot
            // remove a shared old edge twice because the lists update immediately.
            if let Some(index) = previous {
                self.remove_edge(index)?;
            }
            self.remove_edge(left)?;
            self.remove_edge(right)?;
            self.nodes[left].token = output;
            self.nodes[left].next = next;
            self.nodes[right].alive = false;
            if let Some(index) = next {
                self.nodes[index].previous = Some(left);
            }
            if let Some(index) = previous {
                self.add_edge(index)?;
            }
            self.add_edge(left)?;
            replacements = replacements
                .checked_add(self.weights[self.nodes[left].document])
                .ok_or(TokenizerError::Overflow)?;
        }
        Ok(replacements)
    }
    // endregion:local-edge-replacement

    fn snapshot(&self, budget: &mut usize) -> Result<Vec<Vec<u32>>, TokenizerError> {
        let mut sequences = Vec::new();
        for &head in &self.heads {
            let mut sequence = Vec::new();
            let mut current = head;
            while let Some(index) = current {
                if *budget == 0 {
                    return Err(TokenizerError::Resource("trace capacity exceeded"));
                }
                *budget -= 1;
                sequence.push(self.nodes[index].token);
                current = self.nodes[index].next;
            }
            sequences.push(sequence);
        }
        Ok(sequences)
    }

    fn finish(
        mut self,
        policy: TokenizerPolicy,
        binding: TrainingBinding,
        trace_enabled: bool,
    ) -> Result<TrainingResult, TokenizerError> {
        let mut rules = Vec::new();
        let mut trace = Vec::new();
        let mut trace_budget = self.limits.max_trace_values;
        let mut total_replacements = 0u64;
        let merge_layout = TokenizerLayout::new(policy.merge_count)?;
        for rank in 0..policy.merge_count {
            let Some((pair, count)) = self.winner() else {
                break;
            };
            let counts = if trace_enabled {
                let needed = self
                    .pairs
                    .len()
                    .checked_mul(3)
                    .ok_or(TokenizerError::Overflow)?;
                trace_budget = trace_budget
                    .checked_sub(needed)
                    .ok_or(TokenizerError::Resource("trace capacity exceeded"))?;
                self.pairs
                    .iter()
                    .map(|(&pair, state)| PairCount {
                        count: state.count,
                        left: pair.left(),
                        right: pair.right(),
                    })
                    .collect()
            } else {
                Vec::new()
            };
            let token_id = merge_layout
                .merge_token_id(rank)
                .ok_or(TokenizerError::Overflow)?;
            let replacements = self.replace(pair, token_id)?;
            if replacements == 0 {
                return Err(TokenizerError::Invariant("winning pair has no replacement"));
            }
            total_replacements = total_replacements
                .checked_add(replacements)
                .ok_or(TokenizerError::Overflow)?;
            let rule = ArtifactMerge {
                candidate_count: count,
                left: pair.left(),
                rank,
                replacements,
                right: pair.right(),
                token_id,
            };
            if trace_enabled {
                trace.push(RoundTrace {
                    counts,
                    rule: rule.clone(),
                    sequences: self.snapshot(&mut trace_budget)?,
                });
            }
            rules.push(rule);
        }
        if policy.exact_merge_count && rules.len() != policy.merge_count {
            return Err(TokenizerError::Policy(
                "training exhausted pairs before the exact merge count",
            ));
        }
        let artifact = TokenizerArtifact {
            counters: EfficiencyCounters {
                content_tokens: self
                    .input_bytes
                    .checked_sub(total_replacements)
                    .ok_or(TokenizerError::Overflow)?,
                control_tokens: self
                    .documents
                    .checked_mul(2)
                    .ok_or(TokenizerError::Overflow)?,
                input_bytes: self.input_bytes,
                training_documents: self.documents,
            },
            layout_version: TOKENIZER_LAYOUT_VERSION,
            merges: rules,
            policy,
            schema_version: 1,
            trainer_semantics: "overlapping-count-leftmost-replace-v1".into(),
            training: binding,
        };
        // A successful result exists only after all semantic/size checks pass.
        artifact.canonical_bytes(self.limits)?;
        Ok(TrainingResult {
            artifact,
            trace,
            metrics: self.metrics,
        })
    }
}

struct DigestReader<R> {
    inner: R,
    digest: Sha256,
}
impl<R: Read> Read for DigestReader<R> {
    fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {
        let length = self.inner.read(buffer)?;
        self.digest.update(&buffer[..length]);
        Ok(length)
    }
}

/// The caller supplies a training-only stream and separately accepts its corpus
/// evidence. This function verifies exact stream bytes and any supplied split
/// metadata; it does not discover overlap, curate documents or approve rights.
pub(super) fn train_prepared<R: Read>(
    reader: R,
    read_limits: ReadLimits,
    binding: TrainingBinding,
    policy: TokenizerPolicy,
    limits: TokenizerLimits,
    trace: bool,
) -> Result<TrainingResult, TokenizerError> {
    binding.validate()?;
    policy.validate()?;
    if binding.input_encoding != "prepared-jsonl" {
        return Err(TokenizerError::Identity(
            "prepared reader requires a JSONL input binding",
        ));
    }
    let mut source = DigestReader {
        inner: reader,
        digest: Sha256::new(),
    };
    let documents = PreparedCorpusReader::new(BufReader::new(&mut source), read_limits)
        .map_err(|e| TokenizerError::Input(e.to_string()))?;
    let mut engine = Engine::new(limits)?;
    for document in documents {
        let document = document.map_err(|e| TokenizerError::Input(e.to_string()))?;
        if document
            .metadata
            .get("split")
            .is_some_and(|s| s.as_str() != Some("train"))
        {
            return Err(TokenizerError::Identity(
                "held-out split metadata cannot supply training",
            ));
        }
        engine.ingest(document.text.as_bytes(), 1)?;
    }
    if format!("{:x}", source.digest.finalize()) != binding.input_sha256 {
        return Err(TokenizerError::Identity("training stream SHA-256 mismatch"));
    }
    engine.finish(policy, binding, trace)
}

/// Hash the closed weighted-byte fixture representation: little-endian length,
/// positive multiplicity, then raw bytes for each document in source order.
pub fn weighted_input_sha256(documents: &[WeightedBytes]) -> String {
    let mut digest = Sha256::new();
    for document in documents {
        digest.update((document.bytes.len() as u64).to_le_bytes());
        digest.update(document.weight.to_le_bytes());
        digest.update(&document.bytes);
    }
    format!("{:x}", digest.finalize())
}

pub(super) fn train_weighted_fixture(
    documents: &[WeightedBytes],
    binding: TrainingBinding,
    policy: TokenizerPolicy,
    limits: TokenizerLimits,
    trace: bool,
) -> Result<TrainingResult, TokenizerError> {
    binding.validate()?;
    policy.validate()?;
    if binding.scope != "fixture"
        || binding.input_encoding != "weighted-bytes-v1"
        || binding.input_sha256 != weighted_input_sha256(documents)
    {
        return Err(TokenizerError::Identity(
            "weighted fixture identity mismatch",
        ));
    }
    let mut engine = Engine::new(limits)?;
    for document in documents {
        engine.ingest(&document.bytes, document.weight)?;
    }
    engine.finish(policy, binding, trace)
}

// The semantic policy and caller-selected storage bounds for course byte BPE.

use crate::reference_source_identity::lower_hex;
use serde::{Deserialize, Serialize};
